/// Operating system security features the policy tiers are built on.
///
/// These are raw observations, not judgements — the companion reports what it found and
/// the backend decides what it means (ADR 0004). "unknown" is never silently upgraded to
/// "enabled"; a probe that could not answer is itself a signal.
struct SecurityFeatures {
    /// UEFI Secure Boot state.
    FeatureState secureBoot = FeatureState{};
    /// Memory integrity / hypervisor-enforced code integrity.
    FeatureState hvci = FeatureState{};
    /// Windows test signing. Enabled is a fail.
    FeatureState testSigning = FeatureState{};
    /// Kernel debugger attached. Enabled is a fail.
    FeatureState kernelDebugging = FeatureState{};
    /// Microsoft vulnerable driver blocklist.
    FeatureState driverBlocklist = FeatureState{};
    /// IOMMU / kernel DMA protection.
    FeatureState iommu = FeatureState{};
    /// VBS running state.
    FeatureState virtualizationBasedSecurity = FeatureState{};

    Value to_json() const;
    static bool from_json(const Value& value, SecurityFeatures& out, std::string* error);
};

