/// Proof that a FiveM client is running on the same machine as the companion.
///
/// This is the second half of the co-location argument; the localhost hop is the first
/// (ADR 0003). Absence of this evidence denies the connection under every policy tier.
struct GameProcessEvidence {
    /// Process id of the observed FiveM client. (min: 1)
    std::int64_t pid = 0;
    /// Process creation time, milliseconds since epoch. (min: 0)
    std::int64_t startedAtUnixMs = 0;
    /// Executable file name, without any path. (max length: 128)
    std::string imageName;
    /// Whether a top-level window belonging to that process was found.
    bool mainWindowPresent = false;

    Value to_json() const;
    static bool from_json(const Value& value, GameProcessEvidence& out, std::string* error);
};

/// Everything the companion observed for one connect attempt.
///
/// Facts only. There is deliberately no field that says "clean" — a tampered companion
/// can omit facts, and omission is itself evaluated (ADR 0004).
///
/// Privacy: no command lines, no paths below user directories, no document names.
/// Process names are hashed unless they are on a published signature list (design
/// document 13).
struct SystemSnapshot {
    /// Protocol version this snapshot was produced against. (min: 1)
    std::int64_t schemaVersion = 0;
    /// When the scan completed, ISO 8601 UTC. (format: datetime)
    std::string collectedAt;
    /// Companion release version. (format: semver, max length: 32)
    std::string companionVersion;
    /// SHA-256 of the companion binary. Checked against the accepted build list. (format: hex, min length: 64, max length: 64)
    std::string companionBuildHash;
    /// Windows build string, for example "10.0.26100". (max length: 64)
    std::string osBuild;
    /// Security feature states.
    SecurityFeatures features;
    /// TPM presence and identity.
    TpmInfo tpm;
    /// Local FiveM process, absent if none was found.
    std::optional<GameProcessEvidence> gameProcess;
    /// Probes that failed, as short stable identifiers. An empty list is the normal case. (max items: 32)
    std::vector<std::string> probeErrors;

    Value to_json() const;
    static bool from_json(const Value& value, SystemSnapshot& out, std::string* error);
};

