inline Value SystemSnapshot::to_json() const {
    fiveprotect::json::Object object;
    object["schemaVersion"] = Value(static_cast<std::int64_t>(schemaVersion));
    object["collectedAt"] = Value(collectedAt);
    object["companionVersion"] = Value(companionVersion);
    object["companionBuildHash"] = Value(companionBuildHash);
    object["osBuild"] = Value(osBuild);
    object["features"] = features.to_json();
    object["tpm"] = tpm.to_json();
    if (gameProcess.has_value()) {
        object["gameProcess"] = gameProcess.value().to_json();
    }
    object["probeErrors"] = [&]{ fiveprotect::json::Array array; for (const auto& item : probeErrors) { array.push_back(Value(item)); } return Value(std::move(array)); }();
    return Value(std::move(object));
}

inline const char* const SystemSnapshot_known_fields[] = {
    "schemaVersion",
    "collectedAt",
    "companionVersion",
    "companionBuildHash",
    "osBuild",
    "features",
    "tpm",
    "gameProcess",
    "probeErrors",
};

inline bool SystemSnapshot::from_json(const Value& value, SystemSnapshot& out, std::string* error) {
    if (!detail::require_object(value, error, "SystemSnapshot")) return false;
    if (!detail::reject_unknown_fields(value, SystemSnapshot_known_fields, sizeof(SystemSnapshot_known_fields) / sizeof(SystemSnapshot_known_fields[0]), error, "SystemSnapshot")) return false;
    {
        const Value* found = value.find("schemaVersion");
        if (found == nullptr || found->is_null()) return detail::set_error(error, "SystemSnapshot.schemaVersion: missing");
        const Value& field = *found;
        if (!field.is_number()) return detail::set_error(error, "SystemSnapshot.schemaVersion: expected a number");
        if (field.as_int() < 1) return detail::set_error(error, "SystemSnapshot.schemaVersion: below the minimum of 1");
        out.schemaVersion = field.as_int();
    }
    {
        const Value* found = value.find("collectedAt");
        if (found == nullptr || found->is_null()) return detail::set_error(error, "SystemSnapshot.collectedAt: missing");
        const Value& field = *found;
        if (!field.is_string()) return detail::set_error(error, "SystemSnapshot.collectedAt: expected a string");
        if (!detail::is_datetime(field.as_string())) return detail::set_error(error, "SystemSnapshot.collectedAt: does not look like an ISO 8601 timestamp");
        out.collectedAt = field.as_string();
    }
    {
        const Value* found = value.find("companionVersion");
        if (found == nullptr || found->is_null()) return detail::set_error(error, "SystemSnapshot.companionVersion: missing");
        const Value& field = *found;
        if (!field.is_string()) return detail::set_error(error, "SystemSnapshot.companionVersion: expected a string");
        if (field.as_string().size() > 32u) return detail::set_error(error, "SystemSnapshot.companionVersion: longer than 32 characters");
        if (!detail::is_semver(field.as_string())) return detail::set_error(error, "SystemSnapshot.companionVersion: does not look like a semantic version");
        out.companionVersion = field.as_string();
    }
    {
        const Value* found = value.find("companionBuildHash");
        if (found == nullptr || found->is_null()) return detail::set_error(error, "SystemSnapshot.companionBuildHash: missing");
        const Value& field = *found;
        if (!field.is_string()) return detail::set_error(error, "SystemSnapshot.companionBuildHash: expected a string");
        if (field.as_string().size() < 64u) return detail::set_error(error, "SystemSnapshot.companionBuildHash: shorter than 64 characters");
        if (field.as_string().size() > 64u) return detail::set_error(error, "SystemSnapshot.companionBuildHash: longer than 64 characters");
        if (!detail::all_of(field.as_string(), detail::is_hex_digit)) return detail::set_error(error, "SystemSnapshot.companionBuildHash: does not look like hex");
        out.companionBuildHash = field.as_string();
    }
    {
        const Value* found = value.find("osBuild");
        if (found == nullptr || found->is_null()) return detail::set_error(error, "SystemSnapshot.osBuild: missing");
        const Value& field = *found;
        if (!field.is_string()) return detail::set_error(error, "SystemSnapshot.osBuild: expected a string");
        if (field.as_string().size() > 64u) return detail::set_error(error, "SystemSnapshot.osBuild: longer than 64 characters");
        out.osBuild = field.as_string();
    }
    {
        const Value* found = value.find("features");
        if (found == nullptr || found->is_null()) return detail::set_error(error, "SystemSnapshot.features: missing");
        const Value& field = *found;
        if (!SecurityFeatures::from_json(field, out.features, error)) return false;
    }
    {
        const Value* found = value.find("tpm");
        if (found == nullptr || found->is_null()) return detail::set_error(error, "SystemSnapshot.tpm: missing");
        const Value& field = *found;
        if (!TpmInfo::from_json(field, out.tpm, error)) return false;
    }
    if (value.has("gameProcess")) {
        const Value& field = *value.find("gameProcess");
        GameProcessEvidence parsed{};
        if (!GameProcessEvidence::from_json(field, parsed, error)) return false;
        out.gameProcess = std::move(parsed);
    } else {
        out.gameProcess = std::nullopt;
    }
    {
        const Value* found = value.find("probeErrors");
        if (found == nullptr || found->is_null()) return detail::set_error(error, "SystemSnapshot.probeErrors: missing");
        const Value& field = *found;
        if (!field.is_array()) return detail::set_error(error, "SystemSnapshot.probeErrors: expected an array");
        if (field.as_array().size() > 32u) return detail::set_error(error, "SystemSnapshot.probeErrors: holds more than 32 items");
        out.probeErrors.clear();
        for (const Value& element : field.as_array()) {
            std::string item{};
            if (!element.is_string()) return detail::set_error(error, "SystemSnapshot.probeErrors[]: expected a string");
            if (element.as_string().size() > 200u) return detail::set_error(error, "SystemSnapshot.probeErrors[]: longer than 200 characters");
            item = element.as_string();
            out.probeErrors.push_back(std::move(item));
        }
    }
    return true;
}

